test('addLine multiple times', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = invoiceResult.value;

  let result = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);
  invoice = result.value;

  result = addLine(invoice, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(result.ok, true);
  invoice = result.value;

  result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(result.ok, true);
  invoice = result.value;

  assert.equal(invoice.lines.length, 3);
  assert.equal(invoice.lines[0].qty, 3);
  assert.equal(invoice.lines[1].sku, 'LOGO-PACK');
  assert.equal(invoice.lines[2].sku, 'COPY-HOUR');
});

test('removeLine then addLine', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = invoiceResult.value;

  let result = removeLine(invoice, 'DEV-HOUR');
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 1);

  result = addLine(invoice, { sku: 'COPY-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});

